\textbf{Casos de la constante $k$:}
\begin{itemize}
\item $k > 1$: Amplificación de fuerza ($A_2 > A_1$)
\item $k = 1$: Transmisión directa 1:1 ($A_2 = A_1$)
\item $k < 1$: Reducción de fuerza, ganancia en desplazamiento
\end{itemize}

\textbf{Remediación didáctica:}
\begin{enumerate}
\item Derivar explícitamente $A = \pi d^2/4$ en clase
\item Mostrar algebraicamente que $\pi/4$ se cancela en el cociente
\item Visualización geométrica: duplicar lado $\implies$ cuadruplicar área
\end{enumerate}

\textbf{Aprendizaje Basado en Problemas + Representación Múltiple:}
\begin{enumerate}
\item Presentar prototipo real de excavadora hidráulica
\item Formular problema: ¿cómo amplificar fuerza con jeringas?
\item Construir 3 representaciones: tabla, ecuación, gráfica
\item Generalizar modelo $y = kx$ e interpretación física de $k$
\end{enumerate}

\textbf{Solución:}
a) $P = \frac{F_1}{A_1} = \frac{8}{1.767} = 4.53$ N/cm²\\
b) $k = \left(\frac{3.0}{1.5}\right)^2 = 4 \implies F_2 = 32$ N\\
c) $\Delta x_2 = \frac{4}{4} = 1$ cm\\
d) $k' = \left(\frac{6}{1.5}\right)^2 = 16$: pendiente se \alert{cuadruplica}

\textbf{Indicador observable:} El estudiante escribe $F_2 = k \cdot F_1$ con $k = (d_2/d_1)^2$ \alert{sin confundirlo} con $d_2/d_1$, y calcula $\Delta x_2$ usando conservación de volumen.\\[0.2cm]
\textbf{Evidencia concreta:}
\begin{enumerate}
\item Tabla con $\geq 3$ pares $(F_1, F_2)$ correctos
\item Gráfica $F_2$ vs $F_1$ en GeoGebra con pendiente identificada
\item Respuesta escrita al inciso d) con interpretación
\end{enumerate}
